<?php require_once ROOT.'/app/admin-form-helpers.php';$classes=['identity'=>'هوية / شعار','illustration'=>'صورة توضيحية','project'=>'صورة مشروع حقيقي','document'=>'مستند']; ?>
<div class="admin-title"><div><h1>مكتبة الوسائط</h1><p>صور وأصول الشركة مع نصوصها البديلة ومصادرها.</p></div><a class="text-link" href="/admin/media">كل الوسائط</a></div>
<?php if($adminRoute==='media-edit'):$m=media((int)getstr('id'));if(!$m){echo '<div class="notice error">الوسيط غير موجود.</div>';return;}?><div class="admin-card"><?php if(str_starts_with($m['mime'],'image/')):?><?=picture((int)$m['id'],'admin-media-preview')?><?php elseif($m['mime']==='video/mp4'):?><video class="admin-media-preview" src="<?=e(video_url((int)$m['id']))?>" controls preload="none" playsinline aria-label="معاينة الفيديو"></video><?php endif;?><p><a class="text-link" href="/media/<?=$m['id']?>" target="_blank" rel="noopener"><?=e($m['original_name'])?> ↗</a></p><p class="admin-hint">#<?=$m['id']?> · <?=e($m['mime'])?> · <?=number_format($m['size_bytes']/1024,1)?> KB</p></div><form method="post" class="admin-card" data-unsaved><?=csrf_field()?><input type="hidden" name="action" value="save-media"><input type="hidden" name="id" value="<?=$m['id']?>"><?php afield('alt_ar','النص البديل بالعربية',$m['alt_ar'],true);afield('alt_en','النص البديل بالإنكليزية',$m['alt_en'],true,'ltr');aselect('classification','التصنيف',$classes,$m['classification']);afield('source','مصدر الملف وشروط الاستخدام / موافقة الشركة',$m['source'],true,'ltr');?><button class="button">حفظ وصف الوسيط</button></form>
<?php else:?><form class="admin-card" method="post" enctype="multipart/form-data"><h2>رفع وسيط جديد</h2><?=csrf_field()?><input type="hidden" name="action" value="upload"><div class="form-grid"><div class="field"><label for="upload-file">الصورة أو الملف</label><input id="upload-file" name="file" type="file" accept="image/png,image/jpeg,image/webp,application/pdf" required></div><?php aselect('classification','التصنيف',$classes,'illustration');afield('alt_ar','النص البديل بالعربية');afield('alt_en','النص البديل بالإنكليزية','',false,'ltr');?></div><?php afield('source','مصدر الملف وشروط الاستخدام / مرجع الاعتماد','',true);?><p class="admin-hint">PNG / JPEG / WebP حتى 8 MB؛ PDF حتى 40 MB. الصور التوضيحية تعالج لحجم مناسب، بينما تبقى أبعاد الشعار ونسبه محفوظة. لا يقبل SVG أو ملفات تنفيذية.</p><button class="button">رفع الملف</button></form><div class="admin-media-grid"><?php foreach(query('SELECT * FROM media ORDER BY id DESC') as $m):?><article class="admin-media-item"><?php if(str_starts_with($m['mime'],'image/')):?><?=picture((int)$m['id'])?><?php else:?><p><?=$m['mime']==='video/mp4'?'فيديو MP4 ▶':'PDF ↓'?></p><?php endif;?><h2><?=e($m['original_name'])?></h2><p>#<?=$m['id']?> · <?=e($classes[$m['classification']])?></p><a href="/admin/media-edit?id=<?=$m['id']?>">تحرير النص البديل والمصدر</a></article><?php endforeach;?></div><?php endif;?>
